{"code":"// Challenge-v1; see benchmark-sources.md for provenance.
func changeWays(coins: Array<Int64>, total: Int64): Int64 {
    if (total < 0) {
        return 0
    }
    let dp = Array<Int64>(total + 1, repeat: 0)
    dp[0] = 1
    for (coin in coins) {
        if (coin <= 0) {
            continue
        }
        for (x in coin..=total) {
            dp[x] += dp[x - coin]
        }
    }
    dp[total]
}

main() {
    println(changeWays([1, 2], 4) == 3)
    println(changeWays([], 0) == 1)
}
"}

