import std.collection.*
func frequency(words: Array<String>): HashMap<String,Int64> {
    let result = HashMap<String,Int64>()
    for (word in words) {
        let key = word.trimAscii().toAsciiLower()
        if (!key.isEmpty()) {
            if (result.contains(key)) {
                result[key] = result[key] + 1
            } else {
                result[key] = 1
            }
        }
    }
    return result
}

main() {
    let m = frequency([" A ", "a", "B", ""])
    println(m["a"] == 2 && m["b"] == 1 && m.size == 2)
}
"}

