func commonSubstring(a: String, b: String): Int64 {
    let dp = Array<Array<Int64>>(a.size + 1, {_ => Array<Int64>(b.size + 1, repeat: 0)})
    var best: Int64 = 0
    for (i in 1..=a.size) {
        for (j in 1..=b.size) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1
                if (dp[i][j] > best) {
                    best = dp[i][j]
                }
            } else {
                dp[i][j] = 0
            }
        }
    }
    best
}

main() {
    println(commonSubstring("abx", "aby") == 2)
    println(commonSubstring("abc", "axbxc") == 1)
}
"}

