func closedSlice(a: Array<Int64>, lo: Int64, hi: Int64): Array<Int64> {
    let start = max(0, lo)
    let end = min(a.size - 1, hi)
    if (start > end) {
        return Array<Int64>()
    }
    return Array<Int64>(end - start + 1, {i => a[start + i]})
}

main() {
