func shortestPaths(w: Array<Array<Int64>>, start: Int64): Array<Int64> {
    let n = w.size
    let inf: Int64 = 1000000000
    let d = Array<Int64>(n, repeat: inf)
    if (start < 0 || start >= n) {
        return Array<Int64>(n, repeat: -1)
    }
    d[start] = 0
    for (_ in 0..n) {
        for (i in 0..n) {
            if (d[i] < inf) {
                for (j in 0..n) {
                    if (w[i][j] >= 0) {
                        let nd = d[i] + w[i][j]
                        if (nd < d[j]) {
                            d[j] = nd
                        }
                    }
                }
            }
        }
    }
    for (i in 0..n) {
        if (d[i] >= inf) {
            d[i] = -1
        }
    }
    d
}

main() {
    println(shortestPaths([[0,0,-1],[-1,0,2],[-1,-1,0]],0) == [0,0,2])
    println(shortestPaths([[0,-1],[-1,0]],0) == [0,-1])
}
"}

