func editDistance(a: String, b: String): Int64 {
    let n = a.size
    let m = b.size
    let dp = Array<Array<Int64>>(n + 1, {_ => Array<Int64>(m + 1, repeat: 0)})
    for (i in 0..=n) {
        dp[i][0] = i
    }
    for (j in 0..=m) {
        dp[0][j] = j
    }
    for (i in 1..=n) {
        for (j in 1..=m) {
            let cost = if (a[i - 1] == b[j - 1]) { 0 } else { 1 }
            dp[i][j] = min(min(dp[i - 1][j] + 1, dp[i][j - 1] + 1), dp[i - 1][j - 1] + cost)
        }
    }
    dp[n][m]
}

main() {
    println(editDistance("a", "a") == 0)
    println(editDistance("", "ab") == 2)
}
