func maxSegment(a: Array<Int64>): Int64 {
    var ending: Int64 = 0
    var best: Int64 = 0
    for (x in a) {
        ending = ending + x
        if (ending < 0) {
            ending = 0
        }
        if (ending > best) {
            best = ending
        }
    }
    best
}

main() {
    println(maxSegment([5, -2]) == 5)
    println(maxSegment([-5, 4]) == 4)
}
"}

