{"code":"// Challenge-v1; see benchmark-sources.md for provenance.
func knapsack(weights: Array<Int64>, values: Array<Int64>, cap: Int64): Int64 {
 let n = weights.size
 let dp = Array<Int64>(cap + 1, repeat: 0)
 for (i in 0..n) {
  let w = weights[i]
  let v = values[i]
  var c = cap
  while (c >= w) {
   let candidate = dp[c - w] + v
   if (candidate > dp[c]) {
    dp[c] = candidate
   }
   c -= 1
  }
 }
 dp[cap]
}

main() {
println(knapsack([2,3],[3,8],5) == 11)
println(knapsack([2],[3],4) == 3)
}
"}

