func nextPermutation(a: Array<Int64>): Array<Int64> {
    let b = Array<Int64>(a.size, {i => a[i]})
    var i = b.size - 2
    while (i >= 0 && b[i] >= b[i + 1]) {
        i -= 1
    }
    if (i < 0) {
        return Array<Int64>()
    }
    var j = b.size - 1
    while (b[j] <= b[i]) {
        j -= 1
    }
    let temp = b[i]
    b[i] = b[j]
    b[j] = temp
    var left = i + 1
    var right = b.size - 1
    while (left < right) {
        let t = b[left]
        b[left] = b[right]
        b[right] = t
        left += 1
        right -= 1
    }
    b
}

main() {
    println(nextPermutation([1, 3, 2]) == [2, 1, 3])
    println(nextPermutation([1, 2, 2]) == [2, 1, 2])
}
"}

