func shortestPaths(w: Array<Array<Int64>>, start: Int64): Array<Int64> {
    let n = w.size
    let INF: Int64 = 100000
    let d = Array<Int64>(n, repeat: INF)
    d[start] = 0
    for (_ in 0..n) {
        for (i in 0..n) {
            for (j in 0..n) {
                if (w[i][j] >= 0 && d[i] < INF) {
                    let nd = d[i] + w[i][j]
                    if (nd < d[j]) {
                        d[j] = nd
                    }
                }
            }
        }
    }
    for (i in 0..n) {
        if (d[i] == INF) {
            d[i] = -1
        }
    }
    d
}

